import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def get_packages(data):
    result = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-2] + '/' + proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            key = (name, fw['framework'])
            for pkg in fw.get('topLevelPackages', []):
                result.setdefault(key, {})[pkg['id']] = pkg['resolvedVersion']
    return result

b = get_packages(baseline)
a = get_packages(after)

changes = []
for key in sorted(set(list(b.keys()) + list(a.keys()))):
    bp = b.get(key, {})
    ap = a.get(key, {})
    for pkg in sorted(set(list(bp.keys()) + list(ap.keys()))):
        bv = bp.get(pkg)
        av = ap.get(pkg)
        if bv != av:
            changes.append(f'{key[0]} [{key[1]}]: {pkg} {bv} -> {av}')

if changes:
    print('CHANGES:')
    for c in changes:
        print(f'  {c}')
else:
    print('No version changes detected - conversion is version-neutral for packages that existed at same version.')

# Check for version alignments (expected changes)
print()
print('Expected version alignments (highest version policy):')
for key in sorted(b.keys()):
    bp = b.get(key, {})
    ap = a.get(key, {})
    for pkg in sorted(bp.keys()):
        if bp[pkg] != ap.get(pkg, bp[pkg]):
            print(f'  {key[0]} [{key[1]}]: {pkg} {bp[pkg]} -> {ap[pkg]}')
